def make(n):
    # build two identical dicts with n string keys and simple int values
    keys = [f'k{i}' for i in range(n)]
    d1 = {k: i for i, k in enumerate(keys)}
    d2 = {k: i for i, k in enumerate(keys)}
    return [[d1, d2]]

def make(n):
    # create two identical dicts with n string keys mapping to small ints
    d = {f'k{i}': i for i in range(n)}
    return [(d, d)]

def make(n):
    # obj1 has keys k0..k{n-1}, obj2 missing the last one
    obj1 = {f'k{i}': i for i in range(n)}
    obj2 = {f'k{i}': i for i in range(n-1)}
    return [(obj1, obj2)]

def make(n):
    # a dict with n distinct string keys, all mapping to the same simple value
    d = {f'k{i}': i for i in range(n)}
    return [[d, d]]

def make(n):
    # dict1: keys k0..k{n-1}
    # dict2: keys k0..k{n-2} plus 'extra' -> same length, 1 common key
    d1 = {f'k{i}': i for i in range(n)}
    d2 = {f'k{i}': i for i in range(n-1)}
    d2['extra'] = n
    return [[d1, d2]]
